from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    runs = []
    for r in range(3, h):
        c = 3
        while c < w:
            if grid[r][c] == 0:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] != 0:
                c += 1
            if c - start >= 8:
                runs.append(grid[r][start:c])
    line = max(runs, key=len)
    period = len(line)
    for p in range(1, len(line) // 2 + 1):
        if all(line[i] == line[i % p] for i in range(len(line))):
            period = p
            break
    colors = line[:period]
    phases = Counter(
        (colors.index(grid[r][c]) - r - c) % period
        for r in range(3, h)
        for c in range(3, w)
        if grid[r][c] != 0 and grid[r][c] in colors
    )
    phase = phases.most_common(1)[0][0]

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                out[r][c] = colors[(r + c + phase) % period]
    return out
